import sys
import ast

def unique_brands(products):
    return {p['brand'] for p in products}

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        products = ast.literal_eval(data)
    except Exception:
        return
    result = unique_brands(products)
    # Print as a sorted list for consistent output, matching sample format
    # But the samples show insertion order preserved for case 1 and case 2
    # Case 1: Brand A, Brand B - insertion order
    # Case 2: Apple, Bloomsbury, Samsung - insertion order
    # Let's preserve insertion order of first occurrence
    seen = set()
    ordered_brands = []
    for p in products:
        b = p['brand']
        if b not in seen:
            seen.add(b)
            ordered_brands.append(b)
    print(ordered_brands)

if __name__ == '__main__':
    main()
